using System.Text;

using CheatEngine.SDK.Lua.State;
using CheatEngine.SDK.Lua.Tests.Support;
using CheatEngine.SDK.Tests.Shared.NativeLua;

using FsCheck;
using FsCheck.Fluent;

namespace CheatEngine.SDK.Lua.Tests.State;

/// <summary>Generated byte and UTF-16 strings prove that Lua string access preserves its documented contracts.</summary>
[Trait("Category", "NativeLua")]
public sealed class LuaStringFuzzTests
{
	private static readonly Config s_configuration = Config.QuickThrowOnFailure.WithMaxTest(1000).WithEndSize(128);

	[Fact]
	public void Arbitrary_raw_bytes_round_trip_and_undersized_copies_preserve_the_destination()
	{
		LuaTest.RequireNativeLua();
		Prop.ForAll<byte[]>(values =>
		{
			byte[] payload = Bound(values, 512);
			using NativeLuaState state = new(false);
			LuaState L = LuaTest.View(state);
			L.PushString(payload);

			Assert.Equal((nuint) payload.Length, L.RawLength(1));
			Assert.True(L.TryReadUtf8(1, out ReadOnlySpan<byte> read));
			Assert.True(read.SequenceEqual(payload));
			byte[] exact = new byte[payload.Length];
			Assert.True(L.TryCopyUtf8(1, exact, out int written));
			Assert.Equal(payload.Length, written);
			Assert.Equal(payload, exact);
			if (payload.Length > 0)
			{
				byte[] undersized = new byte[payload.Length - 1];
				Array.Fill(undersized, (byte) 0xA5);
				Assert.False(L.TryCopyUtf8(1, undersized, out int refusedWritten));
				Assert.Equal(0, refusedWritten);
				Assert.All(undersized, static value => Assert.Equal(0xA5, value));
			}

			Assert.Equal(LuaType.String, L.TypeOf(1));
			Assert.Equal(1, L.Top);
			return true;
		}).Check(s_configuration);
	}

	[Fact]
	public void Arbitrary_utf16_uses_the_standard_utf8_replacement_oracle()
	{
		LuaTest.RequireNativeLua();
		Prop.ForAll<ushort[]>(values =>
		{
			char[] characters = Array.ConvertAll(values[..Math.Min(values.Length, 128)], static value => (char) value);
			string text = new(characters);
			byte[] expectedUtf8 = Encoding.UTF8.GetBytes(text);
			string expectedText = Encoding.UTF8.GetString(expectedUtf8);

			using NativeLuaState state = new(false);
			LuaState L = LuaTest.View(state);
			L.PushString(text.AsSpan());

			Assert.True(L.TryReadUtf8(1, out ReadOnlySpan<byte> actualUtf8));
			Assert.True(actualUtf8.SequenceEqual(expectedUtf8));
			Assert.True(L.TryReadString(1, out string? actualText));
			Assert.Equal(expectedText, actualText);
			Assert.Equal((nuint) expectedUtf8.Length, L.RawLength(1));
			Assert.Equal(LuaType.String, L.TypeOf(1));
			Assert.Equal(1, L.Top);
			return true;
		}).Check(s_configuration);
	}

	[Fact]
	public void Embedded_nuls_and_malformed_utf8_keep_length_and_decode_with_the_platform_oracle()
	{
		LuaTest.RequireNativeLua();
		byte[] payload = [0x61, 0x00, 0xC0, 0xAF, 0xFF, 0x62];
		using NativeLuaState state = new(false);
		LuaState L = LuaTest.View(state);
		L.PushString(payload);

		Assert.True(L.TryReadUtf8(1, out ReadOnlySpan<byte> bytes));
		Assert.True(bytes.SequenceEqual(payload));
		Assert.True(L.TryReadString(1, out string? text));
		Assert.Equal(Encoding.UTF8.GetString(payload), text);
		Assert.Equal((nuint) payload.Length, L.RawLength(1));
		Assert.Equal(1, L.Top);
	}

	private static byte[] Bound(byte[] values, int maximumLength)
	{
		return values.Length <= maximumLength ? values : values[..maximumLength];
	}
}
